/* iLearn local-first prototype. All views derive from the same saved records. */
const LEGACY_KEY='ilearn-data-v1';
let KEY=LEGACY_KEY, currentUser=null;
const initial=()=>({profile:{name:'Learner',level:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone},subjects:[],topics:[],resources:[],notes:[],questions:[],attempts:[],cards:[],sessions:[],goals:[],activity:[],readNotifications:[]});
let data=initial();
let page='Overview', menuOpen=false, quiz=null, search='';
const save=()=>localStorage.setItem(KEY,JSON.stringify(data));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/><path d="M8 6h8M8 10h6"/>',library:'<path d="M4 5h4v14H4zM10 3h4v16h-4zM16 6l3-1 3 13-3 1z"/>',practice:'<path d="M9 4h11v16H4V4h2M9 2v4H6V2M8 11l2 2 5-5M8 17h8"/>',revision:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.5 9A7 7 0 0 1 18 6l2 1M4 17l2 1a7 7 0 0 0 12.5-3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',notes:'<path d="M5 3h14v18H5zM8 8h8M8 12h8M8 16h5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 13.5v-3l2-1-2-3-2 1-2-1V4H9v2.5l-2 1-2-1-2 3 2 1v3l-2 1 2 3 2-1 2 1V20h6v-2.5l2-1 2 1 2-3z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',flame:'<path d="M12 3c1 4-2 4-2 7-2-1-2-3-2-3-5 5-2 13 4 13s9-6 5-10c0 3-2 3-2 3 1-4-1-7-3-10z"/>',check:'<path d="m5 12 4 4L19 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chevron:'<path d="m9 18 6-6-6-6"/>',spark:'<path d="m12 2 1.8 6.2L20 10l-6.2 1.8L12 18l-1.8-6.2L4 10l6.2-1.8zM19 16l.7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7z"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const nav=[['Overview','grid'],['My Subjects','book'],['Learning Materials','library'],['Practice & Assessments','practice'],['Smart Revision','revision'],['Study Planner','calendar'],['Performance Analytics','chart'],['Notes & Knowledge','notes'],['Learning Goals','target'],['Notifications','bell']];
const subject=id=>data.subjects.find(x=>x.id===id); const topic=id=>data.topics.find(x=>x.id===id);
const dateLabel=d=>d?new Date(/^\d{4}-\d{2}-\d{2}$/.test(d)?d+'T00:00:00':d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'No date';
const datetime=d=>d?new Date(d).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';
const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const progress=id=>{let t=data.topics.filter(x=>x.subjectId===id);return t.length?Math.round(t.reduce((sum,x)=>sum+topicProgress(x),0)/t.length):0};
const record=(type,description)=>data.activity.push({id:uid(),type,description,date:new Date().toISOString()});
const toast=msg=>{let t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3000)};
const button=(label,action,kind='')=>`<button class="button ${kind}" data-action="${action}">${label}</button>`;
const blank=(symbol,title,description,action,label)=>`<div class="blank"><div class="empty-icon">${icon(symbol)}</div><h2>${title}</h2><p>${description}</p>${action?button(`${icon('plus')} ${label}`,action):''}</div>`;
const cardTitle=(title,subtitle,link,linkLabel='View all')=>`<div class="card-title"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${link?`<button class="text-button" data-nav="${link}">${linkLabel} →</button>`:''}</div>`;
function shell(){return `<div class="app"><div class="backdrop ${menuOpen?'show':''}" data-action="menu"></div><aside class="sidebar ${menuOpen?'open':''}"><div class="brand"><span class="brand-mark">${icon('book')}</span> iLearn<span style="color:#80ad88">.</span></div><div class="nav-caption">Main menu</div><nav class="nav" aria-label="Main navigation">${nav.map(([n,i])=>`<button data-nav="${n}" class="${page===n?'active':''}">${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="side-bottom"><button data-nav="Settings">${icon('settings')} Settings</button><div class="sidebar-note">Your personal learning space.<br>Data is saved in this browser.</div></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">Pages &nbsp; / &nbsp; <strong>${esc(page)}</strong></div><div class="top-actions"><button class="icon-button" data-nav="Notifications" aria-label="Notifications">${icon('bell')}</button><button class="profile-button" data-nav="Settings"><span class="avatar">${esc((data.profile.name||'L')[0].toUpperCase())}</span><span class="profile-name">${esc(data.profile.name)}</span>${icon('chevron')}</button></div></header><div class="content">${renderPage()}</div></main></div>`}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 350 190" fill="none"><circle cx="212" cy="89" r="73" fill="#cce4cf"/><circle cx="277" cy="49" r="10" fill="#f4d9aa"/><path d="M85 164h215" stroke="#a8c8aa" stroke-width="2"/><path d="M217 64c-17 0-29 14-29 31v36h60V95c0-17-14-31-31-31z" fill="#4d8060"/><circle cx="217" cy="53" r="19" fill="#e9b68d"/><path d="M198 54c-5-19 9-29 23-26 15 2 20 14 15 23-3-8-8-11-15-12-4 8-13 13-23 15z" fill="#304c39"/><path d="M193 96c-14 6-17 22-25 31l16 9 25-26M241 96c12 7 16 19 25 29l-15 10-25-25" fill="#e8b28c"/><path d="M161 124c20-4 36-2 53 9v30c-19-12-35-13-53-8v-31z" fill="#fffdf4"/><path d="M267 124c-20-4-36-2-53 9v30c19-12 35-13 53-8v-31z" fill="#f4f4e8"/><path d="M214 133v30M170 132c13-2 24 0 36 6M257 132c-13-2-24 0-36 6" stroke="#abc9ac" stroke-width="2"/><path d="M111 154v-24m0 12c-12 0-15-9-15-14 10 0 15 5 15 14zm0-6c0-10 6-16 14-17 1 9-4 16-14 17z" stroke="#7ba788" stroke-width="3" stroke-linecap="round"/><path d="M101 153h21l-3 11h-15z" fill="#d6ad7b"/><path d="m145 50 3 8 8 3-8 3-3 8-3-8-8-3 8-3 3-8z" fill="#e5bc78"/><path d="m286 91 2 6 6 2-6 2-2 6-2-6-6-2 6-2 2-6z" fill="#8ebc98"/></svg></div>`}
function overview(){let topics=data.topics, pct=topics.length?Math.round(topics.reduce((sum,t)=>sum+topicProgress(t),0)/topics.length):0;let upcoming=data.sessions.filter(s=>s.status==='Planned'&&new Date(s.start)>=new Date()).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,3);let goals=data.goals.filter(g=>g.status==='Active');let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);let key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return {label:d.toLocaleDateString(undefined,{weekday:'short'}),count:data.activity.filter(a=>{let x=new Date(a.date);return [x.getFullYear(),String(x.getMonth()+1).padStart(2,'0'),String(x.getDate()).padStart(2,'0')].join('-')===key}).length}});let max=Math.max(1,...days.map(d=>d.count));let dates=new Set(data.activity.map(a=>new Date(a.date).toDateString()));let streak=0, d=new Date();while(dates.has(d.toDateString())){streak++;d.setDate(d.getDate()-1)}
return `<div class="heading-row"><div><div class="eyebrow">Your learning dashboard</div><h1>Good to see you, ${esc(data.profile.name)} 👋</h1><p class="subheading">Here's what's happening with your learning journey.</p></div><div class="date-pill">${icon('calendar')} ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</div></div><div class="hero"><div class="hero-content"><span class="label">A little progress every day</span><h2>Make space for learning.</h2><p>Every great achievement starts with a small step. Pick up where you left off and keep growing.</p>${data.subjects.length?button(`Explore my subjects ${icon('arrow')}`,'go-subjects'):button(`${icon('plus')} Add your first subject`,'add-subject')}</div>${heroArt()}</div><div class="section-title"><div><h2>Learning at a glance</h2><p>A little overview of your progress</p></div></div><div class="stats"><div class="stat"><div class="stat-top">Overall progress <span class="stat-icon">${icon('chart')}</span></div><div class="stat-value">${pct}% <small>average topic progress</small></div></div><div class="stat"><div class="stat-top">My subjects <span class="stat-icon">${icon('book')}</span></div><div class="stat-value">${data.subjects.length} <small>subjects</small></div></div><div class="stat"><div class="stat-top">Study streak <span class="stat-icon">${icon('flame')}</span></div><div class="stat-value">${streak} <small>consecutive days</small></div></div><div class="stat"><div class="stat-top">Completed today <span class="stat-icon">${icon('check')}</span></div><div class="stat-value">${days[6].count} <small>activities</small></div></div></div><div class="section-title"><div><h2>Your learning space</h2><p>Everything you need to keep moving forward</p></div></div><div class="dashboard-grid"><div class="card">${cardTitle('My subjects','Your subjects and topic progress','My Subjects')}${data.subjects.length?`<div class="subject-list">${data.subjects.slice(0,3).map(s=>`<div class="subject-row"><div class="subject-icon">${icon('book')}</div><div class="details"><strong>${esc(s.name)}</strong><span>${data.topics.filter(t=>t.subjectId===s.id).length} topics · ${esc(s.level||'General')}</span><div class="progress"><span style="width:${progress(s.id)}%"></span></div></div><span class="percent">${progress(s.id)}%</span></div>`).join('')}</div>`:`<div class="empty-subjects"><div class="empty-icon">${icon('book')}</div><div><strong>Your subjects will live here</strong><p>Add a subject to start organizing<br>your learning journey.</p><button class="text-button" data-action="add-subject">+ Add subject</button></div></div>`}</div><div class="card">${cardTitle('Upcoming sessions','Make time for what matters','Study Planner')}${upcoming.length?`<div class="list">${upcoming.map(s=>`<div class="list-row"><div class="subject-icon">${icon('calendar')}</div><div class="details"><strong>${esc(s.title)}</strong><span>${datetime(s.start)} · ${s.duration} min</span></div></div>`).join('')}</div>`:`<div class="empty-block"><div class="empty-icon">${icon('calendar')}</div><div><strong>Nothing on the calendar yet</strong><p>Plan a study session and make it a date.</p></div><button class="text-button" data-action="add-session">+ Plan a session</button></div>`}</div></div><div class="bottom-grid"><div class="card">${cardTitle('Weekly activity','Your completed learning activities over the last 7 days','Performance Analytics','View insights')}<div class="chart" aria-label="Activity in the last seven days">${days.map(x=>`<div class="chart-column"><div class="bar-wrap"><div class="bar" style="height:${x.count?Math.max(5,x.count/max*100):2}%" title="${x.count} activities"></div></div><span>${x.label}</span></div>`).join('')}</div><p class="chart-note">${data.activity.length?'Based on your recorded learning activity.':'Complete a topic, practice, or study session to see activity here.'}</p></div><div class="card">${cardTitle('Learning goals','Small steps, big results','Learning Goals')}${goals.length?`<div class="list">${goals.slice(0,3).map(g=>`<div class="list-row"><div class="subject-icon">${icon('target')}</div><div class="details"><strong>${esc(g.title)}</strong><span>${g.date?'Due '+dateLabel(g.date):'No target date'}</span></div><span class="pill">Active</span></div>`).join('')}</div>`:`<div class="empty-block"><div class="empty-icon">${icon('target')}</div><div><strong>Set a goal for yourself</strong><p>Give your learning a little direction.</p></div><button class="text-button" data-action="add-goal">+ Create a goal</button></div>`}</div></div>`}
function head(title,desc,action,label){return `<div class="page-head"><div><div class="eyebrow">Your learning space</div><h1>${title}</h1><p>${desc}</p></div>${action?button(`${icon('plus')} ${label}`,action):''}</div>`}
function subjectsPage(){return head('My Subjects','Organize your subjects and track your topic progress.','add-subject','Add subject')+(data.subjects.length?`<div class="toolbar"><input id="search" placeholder="Search subjects..." value="${esc(search)}" aria-label="Search subjects"></div><div class="page-grid">${data.subjects.filter(s=>s.name.toLowerCase().includes(search.toLowerCase())).map(s=>`<div class="tile"><div class="subject-icon">${icon('book')}</div><h3>${esc(s.name)} ${s.pinned?'📌':''}</h3><p>${esc(s.level||'General')} · ${data.topics.filter(t=>t.subjectId===s.id).length} topics</p><div class="progress"><span style="width:${progress(s.id)}%"></span></div><p style="margin-top:8px">${progress(s.id)}% complete</p><div class="tile-actions"><button class="small-button" data-action="view-subject" data-id="${s.id}">Open subject</button><button class="small-button" data-action="pin-subject" data-id="${s.id}">${s.pinned?'Unpin':'Pin'}</button><button class="small-button" data-action="edit-subject" data-id="${s.id}">Edit</button><button class="small-button" data-action="delete-subject" data-id="${s.id}">Delete</button></div></div>`).join('')}</div>`:blank('book','A fresh start begins here','Add your first subject, then break it down into manageable topics.','add-subject','Add subject'))}
let currentSubject=null;
function subjectPage(){let s=subject(currentSubject);if(!s){page='My Subjects';return subjectsPage()}let ts=data.topics.filter(t=>t.subjectId===s.id);return `<button class="text-button" data-nav="My Subjects">← All subjects</button><div style="height:15px"></div>${head(esc(s.name),`${esc(s.level||'General')} · ${progress(s.id)}% average topic progress`,'add-topic','Add topic')}<div class="notice">Open a topic to upload a PDF or generate a guided lesson. Topic progress follows your selected learning path.</div>${ts.length?`<div class="table-wrap"><table><thead><tr><th>Topic</th><th>Status</th><th>Target date</th><th>Actions</th></tr></thead><tbody>${ts.map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td><span class="pill ${topicStatus(t)==='Completed'?'':'gray'}">${esc(topicStatus(t))} · ${topicProgress(t)}%</span></td><td>${dateLabel(t.date)}</td><td><div class="inline-actions"><button class="small-button" data-action="view-topic" data-id="${t.id}">Open topic</button>${!t.activePath?`<button class="small-button" data-action="cycle-topic" data-id="${t.id}">Change status</button>`:''}<button class="small-button" data-action="edit-topic" data-id="${t.id}">Edit</button><button class="small-button" data-action="delete-topic" data-id="${t.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:blank('notes','No topics yet','Break this subject into topics to make your progress easier to follow.','add-topic','Add topic')}`}
function materialsPage(){let pdfTopics=data.topics.filter(t=>topicPdfs(t).length);return head('Learning Materials','Keep useful learning resources together in one place.','add-resource','Add resource')+`<div class="notice">Save links to resources you can access. Links are not downloaded for offline use; availability and permissions depend on the source. Topic PDFs are saved in this browser.</div>`+(pdfTopics.length?`<div class="section-title"><h2>Topic PDFs</h2></div><div class="page-grid" style="margin-bottom:20px">${pdfTopics.map(t=>`<div class="tile"><div class="subject-icon">${icon('library')}</div><h3>${esc(t.name)}</h3><p>${esc(subject(t.subjectId)?.name||'Subject')} · ${topicPdfs(t).length} PDF${topicPdfs(t).length===1?'':'s'}</p><div class="tile-actions"><button class="small-button" data-action="view-topic" data-id="${t.id}">Open topic</button></div></div>`).join('')}</div>`:'')+(data.resources.length?`<div class="page-grid">${data.resources.map(r=>`<div class="tile"><div class="subject-icon">${icon('library')}</div><h3>${esc(r.title)}</h3><p>${esc(r.type)} · ${esc(subject(r.subjectId)?.name||'Unassigned')} ${r.topicId?'· '+esc(topic(r.topicId)?.name||''):''}</p><p>${esc(r.description||'No description added.')}</p><div class="tile-actions"><a class="small-button" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open resource ↗</a><button class="small-button" data-action="delete-resource" data-id="${r.id}">Delete</button></div></div>`).join('')}</div>`:(pdfTopics.length?'':blank('library','Your library is empty','Add a link to a study guide, video, PDF, or another helpful resource.','add-resource','Add resource')))}
function notesPage(){return head('Notes & Knowledge','A place for your own ideas, summaries and discoveries.','add-note','New note')+(data.notes.length?`<div class="toolbar"><input id="search" placeholder="Search notes..." value="${esc(search)}" aria-label="Search notes"></div><div class="page-grid">${data.notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(search.toLowerCase())).map(n=>`<div class="tile"><span class="pill">${esc(subject(n.subjectId)?.name||'Personal note')}</span><h3>${esc(n.title)} ${n.pinned?'📌':''}</h3><p style="white-space:pre-wrap">${esc(n.body.slice(0,180))}${n.body.length>180?'…':''}</p><p style="margin-top:12px">Updated ${dateLabel(n.updated)}</p><div class="tile-actions"><button class="small-button" data-action="edit-note" data-id="${n.id}">Open / edit</button><button class="small-button" data-action="pin-note" data-id="${n.id}">${n.pinned?'Unpin':'Pin'}</button><button class="small-button" data-action="delete-note" data-id="${n.id}">Delete</button></div></div>`).join('')}</div>`:blank('notes','A little room to think','Create a personal note to capture what you are learning.','add-note','Create note'))}
function plannerPage(){return head('Study Planner','Make a little time for the things you want to learn.','add-session','Plan a session')+(data.sessions.length?`<div class="table-wrap"><table><thead><tr><th>Session</th><th>When</th><th>Duration</th><th>Status</th><th>Actions</th></tr></thead><tbody>${[...data.sessions].sort((a,b)=>a.start.localeCompare(b.start)).map(s=>`<tr><td><strong>${esc(s.title)}</strong><br><span class="meta">${esc(subject(s.subjectId)?.name||'General')}</span></td><td>${datetime(s.start)}</td><td>${s.duration} min</td><td><span class="pill ${s.status==='Completed'?'':'gray'}">${s.status}</span></td><td><div class="inline-actions">${s.status==='Planned'?`<button class="small-button" data-action="complete-session" data-id="${s.id}">Mark complete</button>`:''}<button class="small-button" data-action="edit-session" data-id="${s.id}">Edit</button><button class="small-button" data-action="delete-session" data-id="${s.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:blank('calendar','Make a plan, find your rhythm','Schedule a session and take the next step at your own pace.','add-session','Plan a session'))}
function goalsPage(){return head('Learning Goals','Set an intention and celebrate your progress.','add-goal','Create goal')+(data.goals.length?`<div class="page-grid">${data.goals.map(g=>`<div class="tile"><span class="pill ${g.status==='Completed'?'':'gray'}">${g.status==='Active'&&g.date&&g.date<today()?'Overdue':g.status}</span><h3>${esc(g.title)}</h3><p>${esc(g.description||'Personal goal')} · ${g.date?'Target: '+dateLabel(g.date):'No target date'}</p><p>Completion is marked manually.</p><div class="tile-actions">${g.status==='Active'?`<button class="small-button" data-action="complete-goal" data-id="${g.id}">Mark complete</button>`:''}<button class="small-button" data-action="edit-goal" data-id="${g.id}">Edit</button><button class="small-button" data-action="delete-goal" data-id="${g.id}">Delete</button></div></div>`).join('')}</div>`:blank('target','What are you working towards?','Create a goal to give your learning a clear direction.','add-goal','Create goal'))}
function practicePage(){if(quiz)return quizPage();return head('Practice & Assessments','Test what you know and learn from every attempt.','add-question','Add question')+`<div class="notice"><strong>Practice your way.</strong> Generate questions with Gemini or add your own. AI-generated questions may contain mistakes and are not verified past examination questions.</div><div class="toolbar"><button class="button" data-action="generate-questions">${icon('spark')} Generate with Gemini</button></div><div class="dashboard-grid"><div class="card">${cardTitle('Your question bank',`${data.questions.length} questions`)}${data.questions.length?`<div class="list">${data.questions.map(q=>`<div class="list-row"><div class="details"><strong>${esc(q.text)}</strong><span>${esc(subject(q.subjectId)?.name||'General')} · ${esc(topic(q.topicId)?.name||'No topic')} · ${q.origin==='gemini'?'AI-generated':'Student-created'}</span></div><button class="small-button" data-action="delete-question" data-id="${q.id}">Delete</button></div>`).join('')}</div><div style="margin-top:16px">${button('Start practice '+icon('arrow'),'start-quiz')}</div>`:`<div class="empty-block"><div class="empty-icon">${icon('practice')}</div><div><strong>No questions yet</strong><p>Add a question to create your first practice set.</p></div></div>`}</div><div class="card">${cardTitle('Recent attempts','Submitted practice sessions','Performance Analytics','View analytics')}${data.attempts.length?`<div class="list">${[...data.attempts].reverse().slice(0,5).map(a=>`<div class="list-row"><div class="subject-icon">${icon('check')}</div><div class="details"><strong>${a.correct} / ${a.total} correct</strong><span>${dateLabel(a.date)} · ${a.unanswered} unanswered</span></div><button class="small-button" data-action="review-attempt" data-id="${a.id}">Review</button></div>`).join('')}</div>`:`<div class="empty-block"><div class="empty-icon">${icon('chart')}</div><div><strong>No attempts yet</strong><p>Your submitted practice results will appear here.</p></div></div>`}</div></div>`}
function quizPage(){return head('Practice session','Choose one answer for each question. You can leave questions unanswered.')+`<div class="notice">Untimed practice · ${quiz.length} questions · Your answers are saved when you submit.</div><form id="quiz-form">${quiz.map((q,i)=>`<div class="question"><h3>${i+1}. ${esc(q.text)} ${q.origin==='gemini'?'<span class="pill gray">AI-generated</span>':''}</h3>${q.options.map((o,j)=>`<label><input type="radio" name="q_${q.id}" value="${j}"> ${esc(o)}</label>`).join('')}</div>`).join('')}<div class="inline-actions"><button class="button" type="submit">Submit answers</button><button class="button secondary" type="button" data-action="cancel-quiz">Cancel</button></div></form>`}
function revisionPage(){let due=data.cards.filter(c=>!c.due||c.due<=today());let wrong=data.attempts.flatMap(a=>a.responses.filter(r=>r.answer!==null&&!r.correct).map(r=>({r,a}))).filter(x=>data.questions.some(q=>q.id===x.r.questionId));return head('Smart Revision','Come back to what you have learned and make it stick.','add-card','Create flashcard')+`<div class="dashboard-grid"><div class="card">${cardTitle('Flashcards',`${due.length} due for review`)}${data.cards.length?`<div class="list">${data.cards.map(c=>`<div class="list-row"><div class="details"><strong>${esc(c.front)}</strong><span>${c.due?'Next review: '+dateLabel(c.due):'Ready to review'}</span></div><button class="small-button" data-action="review-card" data-id="${c.id}">Review</button><button class="small-button" data-action="delete-card" data-id="${c.id}">Delete</button></div>`).join('')}</div>`:`<div class="empty-block"><div class="empty-icon">${icon('revision')}</div><div><strong>No flashcards yet</strong><p>Create a card to start a revision habit.</p></div></div>`}</div><div class="card">${cardTitle('Questions to revisit','From your submitted attempts')}${wrong.length?`<div class="list">${wrong.slice(-5).reverse().map(({r})=>`<div class="list-row"><div class="details"><strong>${esc(data.questions.find(q=>q.id===r.questionId)?.text)}</strong><span>Answered incorrectly in practice</span></div></div>`).join('')}</div>`:`<div class="empty-block"><div class="empty-icon">${icon('spark')}</div><div><strong>Nothing to revisit yet</strong><p>Incorrect practice answers will appear here.</p></div></div>`}</div></div>`}
function analyticsPage(){let attempts=data.attempts, total=attempts.reduce((n,a)=>n+a.total,0), correct=attempts.reduce((n,a)=>n+a.correct,0), unanswered=attempts.reduce((n,a)=>n+a.unanswered,0);return head('Performance Analytics','A closer look at your learning, based on submitted practice.')+(attempts.length?`<div class="stats"><div class="stat"><div class="stat-top">Submitted attempts</div><div class="stat-value">${attempts.length}</div></div><div class="stat"><div class="stat-top">Overall accuracy</div><div class="stat-value">${total?Math.round(correct/total*100):0}%</div></div><div class="stat"><div class="stat-top">Correct answers</div><div class="stat-value">${correct}</div></div><div class="stat"><div class="stat-top">Unanswered</div><div class="stat-value">${unanswered}</div></div></div><div class="section-title"><h2>Assessment history</h2></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Score</th><th>Incorrect</th><th>Unanswered</th><th></th></tr></thead><tbody>${[...attempts].reverse().map(a=>`<tr><td>${dateLabel(a.date)}</td><td>${a.correct} / ${a.total} (${Math.round(a.correct/a.total*100)}%)</td><td>${a.total-a.correct-a.unanswered}</td><td>${a.unanswered}</td><td><button class="small-button" data-action="review-attempt" data-id="${a.id}">Review</button></td></tr>`).join('')}</tbody></table></div><p class="chart-note">Accuracy is correct answers divided by all questions, including unanswered questions. More data is needed for reliable topic recommendations.</p>`:blank('chart','Insights will grow with you','Complete and submit a practice session to see your real results here.','go-practice','Go to practice'))}
function notificationsPage(){let items=[...data.sessions.filter(s=>s.status==='Planned'&&new Date(s.start)>new Date()&&new Date(s.start)-new Date()<86400000).map(s=>({id:'session-'+s.id,text:`Upcoming session: ${s.title}`,when:datetime(s.start)})),...data.goals.filter(g=>g.status==='Active'&&g.date&&g.date>=today()&&(new Date(g.date+'T00:00:00')-new Date())<3*86400000).map(g=>({id:'goal-'+g.id,text:`Goal due soon: ${g.title}`,when:dateLabel(g.date)}))];return head('Notifications','A little reminder of what is coming up.')+`<div class="notice">In-app reminders appear here when you open iLearn. Browser or email notifications are not enabled.</div>`+(items.length?`<div class="card"><div class="list">${items.map(n=>`<div class="list-row"><div class="subject-icon">${icon('bell')}</div><div class="details"><strong>${esc(n.text)}</strong><span>${n.when}</span></div><button class="small-button" data-action="read-notification" data-id="${n.id}">${data.readNotifications.includes(n.id)?'Read':'Mark read'}</button></div>`).join('')}</div></div>`:blank('bell','All caught up','Upcoming sessions and goal deadlines will appear here when they are close.'))}
function settingsPage(){return head('Profile & Settings','Make this learning space feel like yours.')+`<div class="notice warning">Your account is on this server; your learning records and PDFs are stored only in this browser. They are not encrypted or protected from other people using this browser, and clearing browser data will remove them.</div><div class="card" style="max-width:650px">${cardTitle('Your profile','These details are used throughout your dashboard.')}<form id="profile-form" class="form-grid" style="margin-top:20px"><div class="field"><label for="profile-name">Display name</label><input id="profile-name" name="name" required maxlength="60" value="${esc(data.profile.name)}"></div><div class="field"><label for="profile-level">Academic level or examination</label><input id="profile-level" name="level" maxlength="100" value="${esc(data.profile.level)}" placeholder="e.g. WASSCE"></div><div class="field"><label>Timezone</label><input value="${esc(data.profile.timezone)}" disabled><small>Dates and times use your browser's local timezone.</small></div><div><button class="button">Save profile</button></div></form></div><div class="card" style="max-width:650px;margin-top:16px">${cardTitle('Account',esc(currentUser?.email||''))}<div class="tile-actions"><button class="button secondary" data-action="sign-out">Sign out</button>${localStorage.getItem(LEGACY_KEY)?'<button class="button secondary" data-action="import-legacy">Copy previous browser workspace</button>':''}</div></div><div class="card" style="max-width:650px;margin-top:16px">${cardTitle('Your data','Export local records or clear the local workspace. PDF files are not included in the JSON export.')}<div class="tile-actions"><button class="button secondary" data-action="export">Export data</button><button class="button secondary" data-action="reset">Clear all local data</button></div></div>`}
function renderPage(){switch(page){case 'Overview':return overview();case 'My Subjects':return subjectsPage();case 'Subject':return subjectPage();case 'Topic':return topicPage();case 'Lesson':return lessonPage();case 'Learning Materials':return materialsPage();case 'Practice & Assessments':return practicePage();case 'Smart Revision':return revisionPage();case 'Study Planner':return plannerPage();case 'Performance Analytics':return analyticsPage();case 'Notes & Knowledge':return notesPage();case 'Learning Goals':return goalsPage();case 'Notifications':return notificationsPage();case 'Settings':return settingsPage();default:return overview()}}
function render(){document.querySelector('#app').innerHTML=shell();renderTopicAfter()}
const field=(label,name,value='',opts={})=>`<div class="field"><label for="f-${name}">${label}</label>${opts.textarea?`<textarea id="f-${name}" name="${name}" ${opts.required?'required':''} maxlength="${opts.max||5000}" placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${opts.type||'text'}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max?`maxlength="${opts.max}"`:''} placeholder="${esc(opts.placeholder||'')}">`}</div>`;
const select=(label,name,options,value='',required=false)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const subjectOptions=()=>[['','Unassigned'],...data.subjects.map(s=>[s.id,s.name])];
const topicOptions=()=>[['','No topic'],...data.topics.map(t=>[t.id,`${subject(t.subjectId)?.name||''} — ${t.name}`])];
function modal(title,description,fields,handler,submit='Save'){document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${title}</h2><p class="description">${description}</p><form id="modal-form"><div class="form-grid">${fields}</div><div class="modal-actions"><button class="button secondary" type="button" data-action="close-modal">Cancel</button><button class="button" type="submit">${submit}</button></div></form></div></div>`;document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();try{if(handler(Object.fromEntries(new FormData(e.target)))!==false){closeModal();save();render();toast('Saved successfully')}}catch(err){toast(err.message||'Could not save. Please try again.')}};document.querySelector('#modal-form input, #modal-form select, #modal-form textarea')?.focus()}
let activeGeneration=null;
function closeModal(){if(activeGeneration){activeGeneration.abort();activeGeneration=null}document.querySelector('#modal-root').innerHTML=''}
function requireUnique(list,name,id,parent){if(list.some(x=>x.id!==id&&x.name.trim().toLowerCase()===name.trim().toLowerCase()&&(!parent||x.subjectId===parent)))throw Error('An item with that name already exists.')}
function subjectModal(s={}){modal(s.id?'Edit subject':'Add a subject','Give your learning a home. You can add topics next.',field('Subject name','name',s.name,{required:true,max:100,placeholder:'e.g. Government'})+field('Academic level or curriculum','level',s.level,{max:100,placeholder:'e.g. WASSCE'}),v=>{v.name=v.name.trim();if(!v.name)throw Error('Please enter a subject name.');requireUnique(data.subjects,v.name,s.id);if(s.id)Object.assign(s,v);else data.subjects.push({id:uid(),...v,pinned:false})})}
function topicModal(t={}){modal(t.id?'Edit topic':'Add a topic',`Organize your learning in ${esc(subject(currentSubject)?.name||'this subject')}.`,field('Topic name','name',t.name,{required:true,max:100,placeholder:'e.g. Systems of government'})+field('Target completion date (optional)','date',t.date,{type:'date'}),v=>{v.name=v.name.trim();if(!v.name)throw Error('Please enter a topic name.');requireUnique(data.topics,v.name,t.id,currentSubject);if(t.id)Object.assign(t,v);else data.topics.push({id:uid(),subjectId:currentSubject,status:'Not started',...v})})}
function resourceModal(){modal('Add a resource','Save a link to a resource. Only HTTP and HTTPS links are supported.',field('Title','title','',{required:true,max:150})+field('Resource URL','url','',{required:true,type:'url',placeholder:'https://...'})+select('Type','type',[['Study guide','Study guide'],['PDF','PDF'],['Video','Video'],['Website','Website'],['Other','Other']])+select('Subject','subjectId',subjectOptions())+select('Topic','topicId',topicOptions())+field('Description','description','',{textarea:true,max:1000}),v=>{let u;try{u=new URL(v.url)}catch{throw Error('Please enter a valid URL.')}if(!['http:','https:'].includes(u.protocol))throw Error('Only HTTP and HTTPS links are allowed.');validateRelation(v);data.resources.push({id:uid(),...v,created:new Date().toISOString()})})}
function validateRelation(v){if(v.topicId&&topic(v.topicId)?.subjectId!==v.subjectId)throw Error('The selected topic must belong to the selected subject.')}
function noteModal(n={}){modal(n.id?'Edit note':'Create a note','Your personal notes stay separate from learning resources.',field('Title','title',n.title,{required:true,max:150})+select('Subject','subjectId',subjectOptions(),n.subjectId)+select('Topic','topicId',topicOptions(),n.topicId)+field('Your note','body',n.body,{textarea:true,required:true,max:10000,placeholder:'Write down what you want to remember...'}),v=>{validateRelation(v);if(n.id)Object.assign(n,v,{updated:new Date().toISOString()});else data.notes.push({id:uid(),...v,updated:new Date().toISOString(),pinned:false})})}
function sessionModal(s={}){modal(s.id?'Edit session':'Plan a session','Times are saved in your browser’s local timezone.',field('Session title','title',s.title,{required:true,max:150,placeholder:'e.g. Review algebra'})+select('Subject','subjectId',subjectOptions(),s.subjectId)+select('Topic','topicId',topicOptions(),s.topicId)+field('Start date and time','start',s.start,{type:'datetime-local',required:true})+field('Duration in minutes','duration',s.duration||'30',{type:'number',required:true,min:1}),v=>{validateRelation(v);v.duration=Number(v.duration);if(!Number.isFinite(v.duration)||v.duration<1||v.duration>1440||!Number.isFinite(new Date(v.start).getTime()))throw Error('Enter a valid date and duration (1–1440 minutes).');if(data.sessions.some(x=>x.id!==s.id&&x.title.trim().toLowerCase()===v.title.trim().toLowerCase()&&x.start===v.start))throw Error('That session is already scheduled.');if(s.id)Object.assign(s,v);else data.sessions.push({id:uid(),...v,status:'Planned'})})}
function goalModal(g={}){modal(g.id?'Edit goal':'Create a goal','Choose a clear outcome you can mark complete yourself.',field('Goal','title',g.title,{required:true,max:150,placeholder:'e.g. Complete five algebra topics'})+field('How will you achieve it?','description',g.description,{textarea:true,max:1000})+field('Target date (optional)','date',g.date,{type:'date'}),v=>{if(g.id)Object.assign(g,v);else data.goals.push({id:uid(),...v,status:'Active'})})}
function questionModal(){modal('Add a practice question','Create a multiple-choice question with one correct answer.',field('Question','text','',{required:true,max:500})+select('Subject','subjectId',subjectOptions())+select('Topic','topicId',topicOptions())+field('Option A','a','',{required:true,max:300})+field('Option B','b','',{required:true,max:300})+field('Option C (optional)','c','',{max:300})+field('Option D (optional)','d','',{max:300})+select('Correct answer','answer',[['0','Option A'],['1','Option B'],['2','Option C'],['3','Option D']],'0')+field('Explanation (optional)','explanation','',{textarea:true,max:1000}),v=>{validateRelation(v);let options=[v.a.trim(),v.b.trim(),v.c.trim(),v.d.trim()];if(!options[0]||!options[1]||!options[Number(v.answer)])throw Error('The correct option and at least A and B are required.');if(options.slice(0,Number(v.answer)+1).some(x=>!x))throw Error('Fill options in order without gaps.');options=options.filter(Boolean);if(new Set(options.map(x=>x.toLowerCase())).size!==options.length)throw Error('Answer options must be distinct.');if(data.questions.some(q=>q.text.trim().toLowerCase()===v.text.trim().toLowerCase()))throw Error('That question already exists.');data.questions.push({id:uid(),text:v.text,subjectId:v.subjectId,topicId:v.topicId,options,answer:Number(v.answer),explanation:v.explanation})})}
function generationModal(selectedTopicId){
  const available=data.subjects.filter(s=>data.topics.some(t=>t.subjectId===s.id));
  if(!available.length){toast('Add a subject and at least one topic before generating questions.');return}
  const root=document.querySelector('#modal-root');
  root.innerHTML=`<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">Generate with Gemini</h2><p class="description">Choose a subject and topic. Generated questions are AI-created, not verified examination questions. Check answers before relying on them.</p><form id="generation-form"><div class="form-grid">${select('Subject','subjectId',available.map(s=>[s.id,s.name]),available[0].id,true)}${select('Topic','topicId',data.topics.filter(t=>t.subjectId===available[0].id).map(t=>[t.id,t.name]),'',true)}${select('Question format','format',[['multiple-choice','Multiple choice'],['true-false','True or false']])}${select('Difficulty','difficulty',[['Easy','Easy'],['Medium','Medium'],['Hard','Hard']],'Medium')}${select('Number of questions','count',Array.from({length:10},(_,i)=>[String(i+1),String(i+1)]),'5')}${select('Examination style','examStyle',[['General','General'],['WASSCE','WASSCE-style']])}${field('Source material (optional)','source','',{textarea:true,max:12000,placeholder:'Paste study material to base your questions on. Do not include sensitive information.'})}<div id="question-pdf-picker" hidden>${select('Choose a PDF','pdfId',[])}</div><div><button class="small-button" id="use-pdf-source" type="button" hidden>Use text from this topic’s PDF</button><p class="meta" id="pdf-source-info"></p></div></div><p class="description" style="margin:12px 0 0">The subject, topic and any source text will be sent to Gemini. Scanned pages use local English OCR (up to 5 pages). Extraction is limited to 12,000 characters; review it before sending. Resource links are not automatically accessed.</p><div id="generation-error" class="notice warning" role="alert" hidden style="margin-top:12px"></div><div class="modal-actions"><button class="button secondary" type="button" data-action="close-modal">Cancel</button><button class="button" type="submit">Generate questions</button></div></form></div></div>`;
  const form=root.querySelector('#generation-form');
  const pdfButton=form.querySelector('#use-pdf-source'), pdfInfo=form.querySelector('#pdf-source-info');let pdfSourceTopicId=null,pdfSourceFileId=null;form.elements.source.addEventListener('input',()=>{pdfSourceTopicId=null;pdfSourceFileId=null});
  const updatePdfButton=()=>{const t=topic(form.elements.topicId.value),pdfs=topicPdfs(t),picker=form.elements.pdfId;picker.innerHTML=pdfs.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');if(topicPdf(t))picker.value=topicPdf(t).id;form.querySelector('#question-pdf-picker').hidden=!pdfs.length;pdfButton.hidden=!pdfs.length;pdfInfo.textContent=''};
  form.elements.subjectId.addEventListener('change',()=>{const topics=data.topics.filter(t=>t.subjectId===form.elements.subjectId.value);form.elements.topicId.innerHTML=topics.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');updatePdfButton()});
  form.elements.topicId.addEventListener('change',updatePdfButton);form.elements.pdfId.addEventListener('change',()=>{pdfInfo.textContent=pdfSourceFileId?'PDF changed. Extract the selected PDF before generating.':''});
  if(selectedTopicId&&topic(selectedTopicId)){form.elements.subjectId.value=topic(selectedTopicId).subjectId;form.elements.subjectId.dispatchEvent(new Event('change'));form.elements.topicId.value=selectedTopicId}updatePdfButton();
  pdfButton.addEventListener('click',async()=>{
    if(activeGeneration)return;
    if(form.elements.source.value&&!confirm('Replace the source text you entered with text from the PDF?'))return;
    const selectedId=form.elements.topicId.value, selectedPdfId=form.elements.pdfId.value, controller=new AbortController(), submit=form.querySelector('[type=submit]');
    activeGeneration=controller;pdfButton.disabled=true;submit.disabled=true;pdfInfo.textContent='Extracting PDF text…';
    try{
      const result=await pdfSource(topic(selectedId),{pdfId:selectedPdfId,signal:controller.signal,onProgress:message=>{pdfInfo.textContent=message}});
      if(controller.signal.aborted)return;
      if(form.elements.topicId.value!==selectedId||form.elements.pdfId.value!==selectedPdfId){pdfInfo.textContent='Topic changed. Select its PDF again.';return}
      form.elements.source.value=result.text;pdfSourceTopicId=selectedId;pdfSourceFileId=selectedPdfId;pdfInfo.textContent=sourceSummary(result);
    }catch(err){if(err.name!=='AbortError')pdfInfo.textContent=err.message||'Could not extract PDF text.'}
    finally{if(activeGeneration===controller)activeGeneration=null;pdfButton.disabled=false;submit.disabled=false}
  });
  form.onsubmit=async e=>{
    e.preventDefault();
    const values=Object.fromEntries(new FormData(form)), s=subject(values.subjectId), t=topic(values.topicId);
    if(!s||!t||t.subjectId!==s.id){root.querySelector('#generation-error').textContent='Please select a valid subject and topic.';root.querySelector('#generation-error').hidden=false;return}if(pdfSourceTopicId&&(pdfSourceTopicId!==t.id||pdfSourceFileId!==form.elements.pdfId.value)){root.querySelector('#generation-error').textContent='The loaded text belongs to a different PDF or topic. Extract the selected PDF or clear the text before generating.';root.querySelector('#generation-error').hidden=false;return}
    const submit=form.querySelector('[type=submit]'), error=root.querySelector('#generation-error');
    submit.disabled=true;submit.textContent='Generating…';error.hidden=true;
    const controller=new AbortController();activeGeneration=controller;
    try {
      const response=await fetch('/api/generate-questions',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({subject:s.name,topic:t.name,format:values.format,difficulty:values.difficulty,examStyle:values.examStyle,count:Number(values.count),source:values.source})});
      let result;try{result=await response.json()}catch{throw Error('The generation service is unavailable. Start the iLearn server or add questions manually.')}
      if(response.status===401){sessionExpired();return}
      if(!response.ok)throw Error(result.error||'Could not generate questions. Please try again or add them manually.');
      if(!Array.isArray(result.questions)||!result.questions.length)throw Error('No questions were returned. Please try again.');
      const normalize=text=>text.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
      const seen=new Set(data.questions.map(q=>normalize(q.text)));let added=0;
      for(const q of result.questions){const key=normalize(q.text);if(seen.has(key))continue;seen.add(key);data.questions.push({id:uid(),...q,subjectId:s.id,topicId:t.id,origin:'gemini',format:values.format,difficulty:values.difficulty,examStyle:values.examStyle,sourcePdfId:pdfSourceFileId||null,sourcePdfName:topicPdfs(t).find(p=>p.id===pdfSourceFileId)?.name||null});added++}
      save();activeGeneration=null;closeModal();render();toast(added?`Added ${added} AI-generated question${added===1?'':'s'}${added<result.questions.length?'; duplicates skipped':''}.`:'All generated questions already exist.');
    }catch(err){if(err.name==='AbortError')return;error.textContent=err.message||'Generation failed. Please try again or add questions manually.';error.hidden=false;submit.disabled=false;submit.textContent='Generate questions';activeGeneration=null}
  };
  form.elements.subjectId.focus();
}
function cardModal(){modal('Create a flashcard','Write a prompt on the front and an answer on the back.',field('Front','front','',{required:true,max:500})+field('Back','back','',{textarea:true,required:true,max:2000})+select('Subject','subjectId',subjectOptions())+select('Topic','topicId',topicOptions()),v=>{validateRelation(v);data.cards.push({id:uid(),...v,interval:0,due:''})})}
function reviewCard(c){document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>Review flashcard</h2><p class="description">${esc(c.front)}</p><div class="notice"><strong>Answer</strong><br>${esc(c.back).replace(/\n/g,'<br>')}</div><p class="description">How well did you remember? Your next review date adjusts to your response.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Close</button><button class="button secondary" data-action="rate-card" data-id="${c.id}" data-rating="again">Again</button><button class="button secondary" data-action="rate-card" data-id="${c.id}" data-rating="hard">Hard</button><button class="button" data-action="rate-card" data-id="${c.id}" data-rating="good">Good</button></div></div></div>`}
function reviewAttempt(a){let html=a.responses.map((r,i)=>{let q=data.questions.find(x=>x.id===r.questionId);if(!q)return '';return `<div class="question"><h3>${i+1}. ${esc(q.text)}</h3><p class="${r.correct?'result-good':'result-bad'}">${r.answer===null?'Unanswered':r.correct?'Correct':'Incorrect'}${r.answer!==null?' · Your answer: '+esc(q.options[r.answer]):''}</p><p>Correct answer: ${esc(q.options[q.answer])}</p>${q.explanation?`<p class="meta">${esc(q.explanation)}</p>`:''}</div>`}).join('');document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>Practice review</h2><p class="description">${a.correct} of ${a.total} correct · ${a.unanswered} unanswered</p>${html}<div class="modal-actions"><button class="button secondary" data-action="close-modal">Close</button></div></div></div>`}
function deleteRecord(collection,id){let arr=data[collection], item=arr.find(x=>x.id===id);if(!item)return;if(collection==='subjects'&&(data.topics.some(x=>x.subjectId===id)||['resources','notes','questions','cards','sessions'].some(k=>data[k].some(x=>x.subjectId===id))))return toast('Remove linked topics and records before deleting this subject.');if(collection==='topics'&&topicPdfs(item).length)return toast('Remove the attached PDF before deleting this topic.');if(collection==='topics'&&item.lesson)return toast('Remove the lesson before deleting this topic.');if(collection==='topics'&&['resources','notes','questions','cards','sessions'].some(k=>data[k].some(x=>x.topicId===id)))return toast('Remove linked records before deleting this topic.');if(collection==='questions'&&data.topics.some(t=>t.lesson?.steps.some(step=>step.questionId===id)))return toast('This question is part of a lesson. Remove the lesson first.');if(collection==='questions'&&data.attempts.some(a=>a.responses.some(r=>r.questionId===id)))return toast('This question belongs to an attempt and cannot be deleted.');if(confirm('Delete this item? This cannot be undone.')){data[collection]=arr.filter(x=>x.id!==id);save();render();toast('Deleted')}}
document.addEventListener('click',e=>{let navButton=e.target.closest('[data-nav]');if(navButton){page=navButton.dataset.nav;menuOpen=false;quiz=null;search='';render();window.scrollTo(0,0);return}let b=e.target.closest('[data-action]');if(!b)return;let action=b.dataset.action,id=b.dataset.id;switch(action){case 'menu':menuOpen=!menuOpen;render();break;case 'sign-out':signOut();break;case 'import-legacy':importLegacyData();break;case 'close-modal':closeModal();break;case 'go-subjects':page='My Subjects';render();break;case 'go-practice':page='Practice & Assessments';render();break;case 'add-subject':subjectModal();break;case 'edit-subject':subjectModal(subject(id));break;case 'pin-subject':{let s=subject(id);s.pinned=!s.pinned;data.subjects.sort((a,b)=>Number(b.pinned)-Number(a.pinned));save();render();break}case 'view-subject':currentSubject=id;page='Subject';render();break;
case 'view-topic':currentTopicId=id;currentSubject=topic(id).subjectId;readerOpen=false;readerPage=1;page='Topic';render();break;
case 'back-subject':readerOpen=false;pdfRenderToken++;page='Subject';render();break;
case 'back-topic':readerOpen=false;page='Topic';render();break;
case 'upload-pdf':uploadPdfModal(topic(currentTopicId));break;
case 'open-pdf':readerOpen=!readerOpen;pdfRenderToken++;readerPage=Math.min(readerPage,topicPdf(topic(currentTopicId)).pages);render();break;
case 'pdf-prev':readerPage=Math.max(1,readerPage-1);render();break;
case 'pdf-next':readerPage=Math.min(topicPdf(topic(currentTopicId)).pages,readerPage+1);render();break;
case 'select-pdf':topic(currentTopicId).activePath='pdf';save();render();toast('PDF is now your active progress path.');break;
case 'select-lesson':topic(currentTopicId).activePath='lesson';save();render();toast('Lesson is now your active progress path.');break;
case 'remove-pdf':{let t=topic(currentTopicId),pdf=topicPdf(t),accountId=currentUser?.id,dbName=PDF_DB;if(pdf&&confirm('Remove the selected PDF and its page-view progress?')){(async()=>{try{await pdfStore('delete',pdf.id,undefined,dbName);if(currentUser?.id!==accountId)return;t.pdfs=t.pdfs.filter(p=>p.id!==pdf.id);if(t.lesson?.sourcePdfId===pdf.id)t.lesson.sourcePdfId=null;for(const q of data.questions)if(q.sourcePdfId===pdf.id)q.sourcePdfId=null;t.selectedPdfId=t.pdfs[0]?.id||null;if(t.activePath==='pdf'&&!t.pdfs.length)t.activePath=t.lesson?'lesson':null;readerOpen=false;save();render();toast('PDF removed.')}catch{toast('Could not remove the PDF.')}})()}break}
case 'generate-lesson':lessonGenerationModal(topic(currentTopicId));break;
case 'start-lesson':{let steps=topic(currentTopicId).lesson.steps;lessonStepIndex=steps.findIndex(x=>!lessonStepDone(x));if(lessonStepIndex<0)lessonStepIndex=steps.length-1;page='Lesson';render();window.scrollTo(0,0);break}
case 'lesson-go':{let n=Number(b.dataset.index),steps=topic(currentTopicId).lesson.steps;if(Number.isInteger(n)&&n>=0&&n<steps.length&&(n===0||lessonStepDone(steps[n-1]))){lessonStepIndex=n;render()}break}
case 'lesson-next':lessonStepIndex++;render();window.scrollTo(0,0);break;
case 'remove-lesson':{let t=topic(currentTopicId);if(confirm('Remove this lesson? Its questions and assessment history will remain in practice.')){t.lesson=null;if(t.activePath==='lesson')t.activePath=topicPdf(t)?'pdf':null;save();render();toast('Lesson removed.')}break}
case 'topic-questions':generationModal(currentTopicId);break;case 'add-topic':topicModal();break;case 'edit-topic':topicModal(topic(id));break;case 'cycle-topic':{let t=topic(id),states=['Not started','In progress','Completed'];t.status=states[(states.indexOf(t.status)+1)%3];if(t.status==='Completed')record('topic',`Completed ${t.name}`);save();render();toast(`Topic: ${t.status}`);break}case 'add-resource':resourceModal();break;case 'add-note':noteModal();break;case 'edit-note':noteModal(data.notes.find(x=>x.id===id));break;case 'pin-note':{let n=data.notes.find(x=>x.id===id);n.pinned=!n.pinned;data.notes.sort((a,b)=>Number(b.pinned)-Number(a.pinned));save();render();break}case 'add-session':sessionModal();break;case 'edit-session':sessionModal(data.sessions.find(x=>x.id===id));break;case 'complete-session':{let s=data.sessions.find(x=>x.id===id);if(s.status!=='Completed'){s.status='Completed';record('session',`Completed ${s.title}`);save();render();toast('Session completed')}break}case 'add-goal':goalModal();break;case 'edit-goal':goalModal(data.goals.find(x=>x.id===id));break;case 'complete-goal':{let g=data.goals.find(x=>x.id===id);g.status='Completed';save();render();toast('Goal completed');break}case 'add-question':questionModal();break;case 'generate-questions':generationModal();break;case 'start-quiz':quiz=[...data.questions];render();window.scrollTo(0,0);break;case 'cancel-quiz':if(confirm('Leave this practice session? Your answers will not be saved.')){quiz=null;render()}break;case 'review-attempt':reviewAttempt(data.attempts.find(x=>x.id===id));break;case 'add-card':cardModal();break;case 'review-card':reviewCard(data.cards.find(x=>x.id===id));break;case 'rate-card':{let c=data.cards.find(x=>x.id===id);c.interval=b.dataset.rating==='again'?1:b.dataset.rating==='hard'?Math.max(1,c.interval):Math.max(1,c.interval?c.interval*2:1);let d=new Date();d.setDate(d.getDate()+c.interval);c.due=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');record('revision','Reviewed a flashcard');save();closeModal();render();toast('Review saved');break}case 'read-notification':if(!data.readNotifications.includes(id))data.readNotifications.push(id);save();render();break;case 'export':{let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ilearn-backup.json';a.click();URL.revokeObjectURL(a.href);break}case 'reset':if(confirm('Clear all iLearn data from this browser? This cannot be undone. The JSON export does not include PDF files.')){indexedDB.deleteDatabase(PDF_DB);data=initial();save();page='Overview';render();toast('Local data cleared')}break;default:if(action.startsWith('delete-')){let map={'delete-subject':'subjects','delete-topic':'topics','delete-resource':'resources','delete-note':'notes','delete-session':'sessions','delete-goal':'goals','delete-question':'questions','delete-card':'cards'};if(map[action])deleteRecord(map[action],id)}}});
document.addEventListener('submit',e=>{if(e.target.id==='lesson-check-form'){e.preventDefault();submitLessonCheck(e.target)}if(e.target.id==='profile-form'){e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(!v.name.trim())return toast('Please enter a name.');data.profile.name=v.name.trim();data.profile.level=v.level.trim();save();render();toast('Profile saved')}if(e.target.id==='quiz-form'){e.preventDefault();let form=new FormData(e.target);let responses=quiz.map(q=>{let value=form.get('q_'+q.id),answer=value===null?null:Number(value);return {questionId:q.id,answer,correct:answer===q.answer}});let a={id:uid(),date:new Date().toISOString(),responses,total:responses.length,correct:responses.filter(r=>r.correct).length,unanswered:responses.filter(r=>r.answer===null).length};data.attempts.push(a);record('assessment','Completed a practice session');save();quiz=null;render();reviewAttempt(a)}});
document.addEventListener('change',e=>{if(e.target.id==='topic-pdf-select'){const t=topic(currentTopicId);if(t&&topicPdfs(t).some(p=>p.id===e.target.value)){t.selectedPdfId=e.target.value;readerOpen=false;readerPage=1;pdfRenderToken++;save();render()}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let position=e.target.selectionStart;search=e.target.value;render();let input=document.querySelector('#search');input.focus();input.setSelectionRange(position,position)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#modal-root').innerHTML)closeModal()});
startAuth();
